class ZipFile::Writer
  attr_reader :byte_size

  def initialize(io = nil)
    @entries = Set.new
    @byte_size = 0
    @output_io = io
    @streamer = nil
    @digest = Digest::MD5.new
  end

  def stream_to(io)
    @output_io = io
  end

  # Receives every byte ZipKit emits, so we can track the archive's size and checksum as it streams out.
  def write(data)
    @output_io.write(data)
    @byte_size += data.bytesize
    @digest.update(data)
    data.bytesize
  end

  def add_file(path, content = nil, compress: true, &block)
    @entries << path
    write_method = compress ? :write_deflated_file : :write_stored_file

    if block
      streamer.public_send(write_method, path) { |sink| block.call(sink) }
    else
      streamer.public_send(write_method, path) { |sink| sink.write(content) }
    end
  end

  def glob(pattern)
    @entries.select { |entry| File.fnmatch(pattern, entry) }.sort
  end

  def exists?(path)
    @entries.include?(path)
  end

  def close
    streamer.close
  end

  def checksum
    Base64.strict_encode64(@digest.digest)
  end

  private
    def streamer
      @streamer ||= ZipKit::Streamer.new(self)
    end
end
